// HMAC-SHA256 verification for staging Baileys webhook
// Verifies x-signature header against HMAC_SECRET_STAGING env var

const crypto = require('crypto');
const signature = $input.item.json.headers?.['x-signature'] || $input.item.json.headers?.['x-baileys-signature'] || '';
const hmacSecret = process.env.HMAC_SECRET_STAGING;
const body = JSON.stringify($input.item.json.body || $input.item.json);

if (!hmacSecret) {
  // No secret configured - skip verification in dev mode
  return { json: { ...$input.item.json, hmac_verified: true, skip_verify: true } };
}

const expectedSignature = 'sha256=' + crypto.createHmac('sha256', hmacSecret).update(body).digest('hex');

// Use timingSafeEqual only if both strings have the same length
const isValid = signature.length === expectedSignature.length && 
  crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature));

if (!isValid && signature) {
  throw new Error('HMAC verification failed - invalid signature');
}

return { json: { ...$input.item.json, hmac_verified: true } };

// Parse Baileys-style webhook body
// Expected format: { messages: [{ key: { remoteJid, id }, message: { ... } }], event: "messages.upsert" }

const body = $input.item.json.body || $input.item.json;
const messages = body.messages || [];

if (!messages || messages.length === 0) {
  // No messages in payload - might be other event type
  return { json: { ...body, parsed: false, skip_processing: true } };
}

const msg = messages[0];
const key = msg.key || {};

// Extract message text
let text = '';
if (msg.message?.conversation) {
  text = msg.message.conversation;
} else if (msg.message?.extendedTextMessage?.text) {
  text = msg.message.extendedTextMessage.text;
} else if (msg.message?.imageMessage?.caption) {
  text = msg.message.imageMessage.caption;
} else if (msg.message?.videoMessage?.caption) {
  text = msg.message.videoMessage.caption;
}

// Extract user JID (phone number)
const remoteJid = key.remoteJid || '';
// Convert JID to phone number (remove @s.whatsapp.net)
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');

const textLower = text.toLowerCase().trim();

// Intent detection keywords
const orderKeywords = ['order', 'buy', 'purchase', 'get proxy', 'want proxy', 'isp', 'residential', 'mobile', 'datacenter'];
const trialKeywords = ['free trial', 'trial', 'free plan', 'try free'];
const statusKeywords = ['status', 'check', 'track', 'where is', 'my order'];
const helpKeywords = ['help', 'menu', 'start', 'hello', 'hi'];

const isOrder = orderKeywords.some(k => textLower.includes(k));
const isTrial = trialKeywords.some(k => textLower.includes(k));
const isStatus = statusKeywords.some(k => textLower.includes(k));
const isHelp = helpKeywords.some(k => textLower.includes(k));

const intent = isOrder ? 'order' : isTrial ? 'free_trial' : isStatus ? 'status' : isHelp ? 'help' : 'unknown';

return {
  json: {
    ...body,
    parsed: true,
    skip_processing: false,
    channel: 'baileys',
    phone: phone,
    user_id: phone,
    remote_jid: remoteJid,
    message_id: key.id || '',
    message_text: text,
    message_raw: msg,
    intent,
    is_order: isOrder,
    is_trial: isTrial,
    is_status: isStatus,
    is_help: isHelp
  }
};

// Prepare idempotency key with staging prefix
// Uses staging: prefix to avoid collision with prod

const messageId = $input.item.json.message_id || '';
const phone = $input.item.json.phone || '';
const idempotencyKey = `staging:idempotency:baileys:${messageId || phone}`;

return {
  json: {
    ...$input.item.json,
    idempotency_key: idempotencyKey
  }
};

// Parse LLM response

let content = $input.item.json.choices?.[0]?.message?.content || '';
let parsed = { intent: 'unknown', entities: {} };

try {
  if (typeof content === 'string') {
    content = content.replace(/^```json\n?/, '').replace(/\n?```$/, '');
    parsed = JSON.parse(content);
  }
} catch (e) {
  // Use keyword fallback
  const msg = ($input.item.json.message_text || '').toLowerCase();
  parsed = {
    intent: msg.includes('order') || msg.includes('buy') ? 'order' : 
           msg.includes('trial') ? 'free_trial' : 
           msg.includes('status') ? 'status' : 
           msg.includes('help') ? 'help' : 'unknown',
    entities: {}
  };
}

return {
  json: {
    ...$input.item.json,
    intent: parsed.intent || 'unknown',
    entities: parsed.entities || {},
    llm_raw: content
  }
};

// Intent switch - route based on LLM-parsed intent

const intent = $input.item.json.intent;

return {
  json: {
    ...$input.item.json,
    intent_routed: intent
  }
};

// Generate help menu
const message = `🇳🇬 *Styxproxy Proxy*

I can help you with:

🛒 *Order* — ISP, Residential, Mobile, Datacenter
💳 *Check Status* — Track your order
💰 *Pricing* — See all plans
❓ *Help* — How to get started
🔗 *Free Trial* — Get a free proxy

What would you like to do?`;

return { json: { ...$input.item.json, reply_message: message } };
